<?php
namespace Modules\DealerManagement\Http\Controllers\Portal;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Modules\DealerManagement\Services\DealerContext; use Modules\DealerManagement\Services\NotificationService;
class ReorderController extends Controller {
 public function index(){ $ctx=app(DealerContext::class); $u=$ctx->user(); $balances=DB::table('dlr_stock_balances')->where('dealer_id',$u->dealer_id)->whereIn('outlet_id',$ctx->outletIds()?:[0])->orderBy('product_name')->get(); $rules=DB::table('dlr_reorder_rules')->where('dealer_id',$u->dealer_id)->get()->keyBy(fn($r)=>$r->outlet_id.'-'.$r->product_id.'-'.($r->variation_id??'0')); return view('dealermanagement::stock.reorder',compact('balances','rules')); }
 public function save(Request $r){ $ctx=app(DealerContext::class); $u=$ctx->user(); abort_unless((int)$u->is_dealer_admin===1,403); $d=$r->validate(['balance_id'=>'required|integer','min_qty'=>'required|numeric|min:0','max_qty'=>'required|numeric|min:0','reorder_level'=>'required|numeric|min:0','safety_stock_qty'=>'required|numeric|min:0','stock_cover_days'=>'required|integer|min:1','avg_daily_usage'=>'required|numeric|min:0','notes'=>'nullable|string']); $b=DB::table('dlr_stock_balances')->where('id',$d['balance_id'])->where('dealer_id',$u->dealer_id)->first(); abort_unless($b,404); DB::table('dlr_reorder_rules')->updateOrInsert(['business_id'=>$u->business_id,'dealer_id'=>$u->dealer_id,'outlet_id'=>$b->outlet_id,'product_id'=>$b->product_id,'variation_id'=>$b->variation_id],['min_qty'=>$d['min_qty'],'max_qty'=>$d['max_qty'],'reorder_level'=>$d['reorder_level'],'safety_stock_qty'=>$d['safety_stock_qty'],'stock_cover_days'=>$d['stock_cover_days'],'avg_daily_usage'=>$d['avg_daily_usage'],'notes'=>$d['notes']??null,'is_active'=>1,'created_at'=>now(),'updated_at'=>now()]); app(NotificationService::class)->refresh((int)$u->business_id,(int)$u->dealer_id,$ctx->outletIds()); return back()->with('status','Re-order rule saved.'); }
}
